SRC = (ROOT / "platform" / "app.py").read_text()
TREE = ast.parse(SRC)


def func_src(name):
    for node in ast.walk(TREE):
        if isinstance(node, ast.FunctionDef) and node.name == name:
            return ast.get_source_segment(SRC, node) or ""
    return ""


# --- the two post figures -------------------------------------
check(pricing.POST_COST_CENTS_PER_SECOND == 0.01,
      "true post cost must be the cut figure, 0.01c/s")
check(pricing.SHELF_POST_COST_CENTS_PER_SECOND == 0.1,
      "shelf post figure must stay frozen at the pre-cut 0.1c/s")
check(pricing.public_pricing()["post_cost_cents_per_second"] == 0.01,
      "public pricing must report the cut post figure")

# --- owner pays true cost, on every lane ----------------------
for model, resmap in pricing.PROVIDER_RATES_CENTS_PER_SECOND.items():
    for res, rate in resmap.items():
        check(close(pricing.per_second_lane_cost_cents(model, res),
                    rate + 0.01),
              f"{model} {res}: true lane cost is not rate + 0.01")
        # The shelf basis carries the lane's frozen shelf rate
        # where one is recorded (MAGI-2, frozen at its pre-
        # reroute $0.08/s on 2026-11-26), else the live rate.
        shelf_rate = pricing.SHELF_PROVIDER_RATES_CENTS_PER_SECOND \
            .get(model, {}).get(res, rate)
        check(close(pricing.per_second_shelf_cost_cents(model, res),
                    shelf_rate + 0.1),
              f"{model} {res}: shelf lane cost is not shelf rate + 0.1")
        owner_pic = pricing.frontier_lane(model, res, owner=True)
        check(close(owner_pic["sell_cents_per_second"],
                    round(rate + 0.01, 3)),
              f"{model} {res}: owner sell is not the cut raw cost")

# The worked example (FrameHush Seedance 2.5, owner $/s in cents).
for res, want in (("480p", 3.51), ("720p", 4.71), ("1080p", 8.01)):
    pic = pricing.frontier_lane("seedance", res, owner=True)
    check(close(pic["sell_cents_per_second"], want),
          f"seedance {res}: owner sell {pic['sell_cents_per_second']} != {want}")

# --- flat lanes: true raw carries the cut figure --------------
for model, resmap in pricing.FLAT_CLIP_COST_CENTS.items():
    for res, flat in resmap.items():
        for seconds in (4, 8, 30):
            raw = pricing.flat_clip_raw_cents(model, res, seconds)
            want = flat * pricing.flat_clip_segments(model, seconds) \
                + 0.01 * seconds
            check(close(raw, want, 1e-6),
                  f"{model} {res} {seconds}s: flat raw is not cut-based")

# --- the freeze: no customer figure moves ---------------------
# Exception, 2026-11-27: Veo 3.1 (veo3) moved from Kie
# to UnificAlly in the catalog route audit. A flat
# per-clip lane has no shelf: its debit is the true
# flat cost x1.25 by construction, so its snapshot
# entries were regenerated on the new route's costs
# ($1.20 / $1.225 / $1.80 per clip). Every per-second
# lane's figures are unchanged, frozen on shelves.
for (model, res), want in SELL_SNAPSHOT.items():
    pic = pricing.frontier_lane(model, res)
    check(close(pic["sell_cents_per_second"], want),
          f"{model} {res}: customer sell moved {want} -> "
          f"{pic['sell_cents_per_second']}")
    check(close(pic["minimum_cents_per_second"],
                MINIMUM_SNAPSHOT[(model, res)]),
          f"{model} {res}: customer minimum moved")
for (model, res, seconds), want in DEBIT_SNAPSHOT.items():
    got = pricing.per_second_balance_debit_cents(model, res, seconds)
    check(got == want,
          f"{model} {res} {seconds}s: customer debit moved {want} -> {got}")

# --- faststart on every delivered-file write ------------------
check(SRC.count('"-movflags", "+faststart", str(out_path)]') == 5,
      "the five finishing outputs must be written faststart")
check(SRC.count('"-movflags", "+faststart", str(swapped_path)]') == 2,
      "both word-fix swaps must be written faststart")
check(SRC.count('"-movflags", "+faststart", str(burned_path)]') == 1,
      "the caption burn-in must be written faststart")
for fn in ("_process_api_file", "_process_file"):
    check("+faststart" in func_src(fn), f"{fn} lost its faststart write")

if failures:
    print(f"FAIL ({len(failures)})")
    for failure in failures:
        print(" -", failure)
    sys.exit(1)
print("PASS check_post_cost_cut")
